{
    "permissions": {
        "allow": [
            "Read",
            "Edit",
            "Write",
            "NotebookEdit",
            "Bash(journal:*)",
            "Bash(ls:*)",
            "Bash(git status:*)",
            "Bash(git diff:*)",
            "Bash(git log:*)"
        ],
        "deny": [
            "Agent",
            "Task",
            "Workflow",
            "SendMessage",
            "ListAgents",
            "RemoteTrigger",
            "Skill",
            "Bash(claude:*)",
            "Bash(codex:*)",
            "Bash(*claude -p*)",
            "Bash(*codex exec*)",
            "Read({folder:files}/hook-replies.key)"
        ],
        "defaultMode": "bypassPermissions"
    },
    "skipDangerousModePermissionPrompt": true,
    "effortLevel": "high",
    "hooks": {
        "SessionStart": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ],
        "UserPromptSubmit": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ],
        "PreToolUse": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ],
        "PostToolUse": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ],
        "Stop": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ],
        "SessionEnd": [
            {
                "hooks": [
                    {
                        "type": "command",
                        "command": "/opt/journal/bin/journal-hook claude-code {folder:files}/hook-replies.json"
                    }
                ]
            }
        ]
    }
}

